-- ---------------------------------------------------------------- integrity triggers

CREATE OR REPLACE TRIGGER trg_incident_report_lock
BEFORE UPDATE OR DELETE ON incident_report
FOR EACH ROW
BEGIN
  IF UPDATING AND :OLD.locked_at IS NOT NULL THEN
    RAISE_APPLICATION_ERROR(-20002, 'Incident report is locked: approved records cannot be modified');
  END IF;
  IF DELETING AND :OLD.status <> 'DRAFT' THEN
    RAISE_APPLICATION_ERROR(-20003, 'Only draft incident reports can be deleted');
  END IF;
END;
/

CREATE OR REPLACE TRIGGER trg_incident_timeline_lock
BEFORE INSERT OR UPDATE OR DELETE ON incident_timeline
FOR EACH ROW
DECLARE
  v_locked TIMESTAMP WITH TIME ZONE;
  v_report NUMBER(19);
BEGIN
  v_report := CASE WHEN DELETING THEN :OLD.report_id ELSE :NEW.report_id END;
  SELECT MAX(locked_at) INTO v_locked FROM incident_report WHERE report_id = v_report;
  IF v_locked IS NOT NULL OR (UPDATING AND :OLD.report_id <> :NEW.report_id) THEN
    RAISE_APPLICATION_ERROR(-20002, 'Incident report is locked: approved records cannot be modified');
  END IF;
END;
/

